const customers = $input.all();
const now = new Date();
const today = now.getTime();
const oneDay = 24 * 60 * 60 * 1000;

const followUps = [];

for (const cust of customers) {
  const c = cust.json;
  const lastContact = c.tanggal_kontak_terakhir || c.last_contact;
  const lastPurchase = c.tanggal_pembelian_terakhir || c.last_purchase;
  const status = (c.status || '').toLowerCase();

  if (status === 'inactive' || status === 'blacklist') continue;

  const lastContactDate = lastContact ? new Date(lastContact).getTime() : 0;
  const lastPurchaseDate = lastPurchase ? new Date(lastPurchase).getTime() : 0;
  const daysSinceContact = Math.floor((today - lastContactDate) / oneDay);
  const daysSincePurchase = Math.floor((today - lastPurchaseDate) / oneDay);

  let followUpType = null;
  let priority = 'normal';
  let message = '';
  const nama = c.nama || c.name || 'Pelanggan';
  const sapaan = c.sapaan || 'Bapak/Ibu';

  // New lead - not yet contacted
  if (status === 'lead' && daysSinceContact > 1) {
    followUpType = 'new_lead';
    priority = 'high';
    message = `Selamat pagi ${sapaan} ${nama} 🙏\n\nPerkenalkan, saya dari ${c.sales_name || 'Tim Sales'}. Terima kasih sudah tertarik dengan produk kami.\n\nApakah ada yang bisa kami bantu? Kami siap memberikan penawaran terbaik untuk Anda.\n\nTerima kasih 🙏`;
  }
  // Quoted but no response for 3 days
  else if (status === 'quoted' && daysSinceContact >= 3) {
    followUpType = 'quote_followup';
    priority = 'high';
    message = `Selamat pagi ${sapaan} ${nama} 🙏\n\nMohon maaf mengganggu, kami ingin follow up mengenai penawaran yang sudah kami kirimkan sebelumnya.\n\nApakah ada pertanyaan atau hal yang perlu kami jelaskan lebih lanjut?\n\nKami juga bisa menyesuaikan penawaran sesuai kebutuhan ${sapaan}.\n\nTerima kasih 🙏`;
  }
  // Customer hasn't purchased in 30 days
  else if ((status === 'customer' || status === 'pelanggan') && daysSincePurchase >= 30) {
    followUpType = 'repeat_purchase';
    priority = daysSincePurchase > 60 ? 'high' : 'normal';
    message = `Selamat pagi ${sapaan} ${nama} 🙏\n\nSemoga ${sapaan} selalu dalam keadaan baik. Kami ingin menanyakan kabar dan apakah ada kebutuhan yang bisa kami bantu?\n\n${daysSincePurchase > 60 ? 'Sudah lama kami tidak bertemu, kami punya promo spesial untuk pelanggan setia! 🎉' : 'Kami sedang ada penawaran menarik yang mungkin cocok untuk kebutuhan Anda.'}\n\nTerima kasih selalu mempercayai kami 🙏`;
  }
  // After-sales check - 7 days after purchase
  else if (status === 'delivered' && daysSincePurchase >= 7 && daysSincePurchase <= 14) {
    followUpType = 'after_sales';
    priority = 'normal';
    message = `Selamat pagi ${sapaan} ${nama} 🙏\n\nSemoga barang yang ${sapaan} terima dalam kondisi baik. Bagaimana pengalaman menggunakan produk kami?\n\nJika ada kendala atau pertanyaan, jangan ragu untuk menghubungi kami ya.\n\nTerima kasih 🙏`;
  }

  if (followUpType) {
    followUps.push({
      json: {
        customer_id: c.customer_id || c.id,
        nama: nama,
        sapaan: sapaan,
        whatsapp: c.whatsapp || c.no_hp || c.phone,
        email: c.email || '',
        kota: c.kota || c.city || '-',
        status: status,
        follow_up_type: followUpType,
        priority: priority,
        days_since_contact: daysSinceContact,
        days_since_purchase: daysSincePurchase,
        message: message,
        sales_name: c.sales_name || c.pic || '-'
      }
    });
  }
}

// Sort by priority (high first)
followUps.sort((a, b) => (a.json.priority === 'high' ? -1 : 1));

return followUps.length > 0 ? followUps : [{json: {no_followup: true}}];
